challenge.solutionExample:
terraform {
  required_version = ">= 1.5.0"

  backend "s3" {
    bucket         = "company-tf-state"
    key            = "prod/app.tfstate"
    region         = "eu-central-1"
    encrypt        = true
    dynamodb_table = "terraform-locks"
  }
}

provider "aws" {
  region = "eu-central-1"
}
